"""Generate stable wire-framing constants independently of schema identity."""

from pathlib import Path

RUN_LOG_MAX_RECORD_BYTES = 1048576
RUN_LOG_MAGIC = "VSRLOG01"
HOST_API_MAX_MESSAGE_BYTES = 20 * 1024 * 1024
ORCHESTRATOR_MAX_MESSAGE_BYTES = 4 * 1024 * 1024


def generate(root: Path) -> None:
    """Publish the one framing contract in every language, without schema digests."""
    (root / "libs/vs-proto/src/vs_proto/_generated/framing.py").write_text(
        '"""Generated by scripts/generate_proto.sh; do not edit."""\n\n'
        f'RUN_LOG_MAX_RECORD_BYTES = {RUN_LOG_MAX_RECORD_BYTES}\nRUN_LOG_MAGIC = b"{RUN_LOG_MAGIC}"\n'
        f"HOST_API_MAX_MESSAGE_BYTES = {HOST_API_MAX_MESSAGE_BYTES}\n",
        encoding="utf-8",
    )
    (root / "clients/libs/proto/src/generated/framing.ts").write_text(
        "// Generated by scripts/generate_proto.sh; do not edit.\n"
        f"export const RUN_LOG_MAX_RECORD_BYTES = {RUN_LOG_MAX_RECORD_BYTES};\n"
        f"export const RUN_LOG_MAGIC = '{RUN_LOG_MAGIC}';\n"
        f"export const HOST_API_MAX_MESSAGE_BYTES = {HOST_API_MAX_MESSAGE_BYTES};\n",
        encoding="utf-8",
    )
    (root / "gateway/gen/framing.go").write_text(
        "// Code generated by scripts/generate_proto.sh. DO NOT EDIT.\n\npackage gen\n\n"
        f'const RunLogMaxRecordBytes = {RUN_LOG_MAX_RECORD_BYTES}\nconst RunLogMagic = "{RUN_LOG_MAGIC}"\n'
        f"const HostAPIMaxMessageBytes = {HOST_API_MAX_MESSAGE_BYTES}\n",
        encoding="utf-8",
    )
    go_limits = (
        (
            "client",
            "MaxReceiveMessageBytes",
            "the explicit receive limit for the orchestrator link",
        ),
        (
            "daemon",
            "MaxWatchFrameBytes",
            "the receive limit used on the orchestrator link",
        ),
    )
    for package, name, doc in go_limits:
        (root / f"orchestrator/internal/{package}/framing_generated.go").write_text(
            "// Code generated by scripts/generate_proto.sh. DO NOT EDIT.\n\n"
            f"package {package}\n\n"
            f"// {name} is {doc}.\n"
            f"const {name} = {ORCHESTRATOR_MAX_MESSAGE_BYTES}\n",
            encoding="utf-8",
        )
    (root / "clients/libs/orchestrator-proto/src/framing.generated.ts").write_text(
        "// Generated by scripts/generate_proto.sh; do not edit.\n"
        "/** Maximum encoded response on the orchestrator link; checked before allocating a frame. */\n"
        f"export const ORCHESTRATOR_MAX_MESSAGE_BYTES = {ORCHESTRATOR_MAX_MESSAGE_BYTES};\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    generate(Path(__file__).resolve().parents[1])
